    Step(new Operation.Withdraw(70), new(AtmStatus.Ok, new(1, 1, 0), 0, new(80, 160)), new(0, 1, 1));
    // 40 € : le plafond (160 + 40 = 200) passe, mais il ne reste qu'un 20 utilisable.

